#pragma once

#include <string>

// Built-in fonts, used whenever a theme names no font family or names one that
// is missing. On macOS the default is Apple's SF Mono, which ships inside
// Terminal.app rather than as an installed font. Everywhere else, and when that
// folder is missing, it is JetBrains Mono compiled into the addon
// (ofxOceanodeEmbeddedFontData.cpp, generated by scripts/embed_fonts.py), so no
// app depends on bin/data/config/font for its default look.
namespace ofxOceanodeFonts {
    // Folder holding Apple's SF Mono faces; empty off macOS or when it is missing.
    std::string systemFontDirectory();
    // Absolute paths of the system regular and bold faces; empty when unavailable.
    std::string systemRegularPath();
    std::string systemBoldPath();
    // What the built-in default resolves to on this machine, for the Theme Editor.
    std::string builtinDescription();

    // A face compressed in ImGui's stb format for AddFontFromMemoryCompressedTTF.
    struct Embedded {
        const unsigned int* data = nullptr;
        unsigned int size = 0;
    };
    Embedded embeddedRegular();
    Embedded embeddedBold();
}

namespace ofxOceanodeEmbeddedFonts {
    extern const unsigned int JetBrainsMonoMedium_compressed_size;
    extern const unsigned int JetBrainsMonoMedium_compressed_data[];
    extern const unsigned int JetBrainsMonoExtraBold_compressed_size;
    extern const unsigned int JetBrainsMonoExtraBold_compressed_data[];
}
